draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20, H/2 + 150 + 20*Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20, H/2 + 150 + 20*Math.sin(t + Math.PI));
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 50, H/2 - 50, 100, 20);
  ctx.fillStyle = 'white';
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('The Millionaire Next Door', W/2, H/2 - 35);

  // habits
  ctx.fillStyle = 'black';
  ctx.font = '14px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Live below your means', 10, 10 + 20*Math.sin(t));
  ctx.fillText('Invest wisely', 10, 30 + 20*Math.sin(t + Math.PI/2));
  ctx.fillText('Build multiple income streams', 10, 50 + 20*Math.sin(t + Math.PI));

  ctx.restore();
}
